import { Array, Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { childAttributes, html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import { defaultAnchor, selectedIcon } from "../../ui/combobox/view";
import * as Combobox from "../../ui/shadcn-combobox";

type Framework = "Next.js" | "SvelteKit" | "Nuxt.js" | "Remix" | "Astro";

const FrameworkCombobox = Combobox.create<Framework>();
const frameworks: readonly Framework[] = [
  "Next.js",
  "SvelteKit",
  "Nuxt.js",
  "Remix",
  "Astro",
];

// MODEL

export const Model = S.Struct({
  combobox: Combobox.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotComboboxMessage = m("GotComboboxMessage", {
  message: Combobox.Message,
});

export const Message = S.Union([GotComboboxMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [combobox, comboboxCommands] = Combobox.init({
    id: "combobox-basic",
  });

  return [
    { combobox },
    Command.mapMessages(comboboxCommands, (message) =>
      GotComboboxMessage({ message })
    ),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotComboboxMessage: ({ message }) => {
        const [combobox, comboboxCommands] = FrameworkCombobox.update(
          model.combobox,
          message
        );

        return [
          evo(model, { combobox: () => combobox }),
          Command.mapMessages(comboboxCommands, (message) =>
            GotComboboxMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

const filterFrameworks = (inputValue: string): readonly Framework[] =>
  inputValue === ""
    ? frameworks
    : Array.filter(frameworks, (framework) =>
        framework.toLowerCase().includes(inputValue.toLowerCase())
      );

const viewInputs = (inputValue: string): Combobox.ViewInputs<Framework> => {
  const h = html<Message>();

  return {
    items: filterFrameworks(inputValue),
    itemToConfig: (framework, context) => ({
      className: Combobox.shadcnComboboxItemClassName,
      content: h.div(
        [h.Class("flex items-center gap-2")],
        [selectedIcon(context.isSelected), h.span([], [framework])]
      ),
    }),
    itemToValue: (framework) => framework,
    itemToDisplayText: (framework) => framework,
    inputAttributes: childAttributes([
      h.Class(Combobox.shadcnComboboxInputClassName),
      h.Placeholder("Select framework..."),
      h.AriaLabel("Framework"),
    ]),
    inputWrapperAttributes: childAttributes([
      h.Class(Combobox.shadcnComboboxInputWrapperClassName),
    ]),
    itemsAttributes: childAttributes([
      h.Class(Combobox.shadcnComboboxItemsClassName),
    ]),
    backdropAttributes: childAttributes([
      h.Class(Combobox.shadcnComboboxBackdropClassName),
    ]),
    attributes: childAttributes([
      h.Class(Combobox.shadcnComboboxWrapperClassName),
    ]),
    buttonContent: h.span([], ["v"]),
    buttonAttributes: childAttributes([
      h.Class(Combobox.shadcnComboboxButtonClassName),
    ]),
    anchor: defaultAnchor,
  };
};

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-8")],
    [
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], ["Basic"]),
          h.submodel({
            slotId: model.combobox.id,
            model: model.combobox,
            view: FrameworkCombobox.view,
            viewInputs: viewInputs(model.combobox.inputValue),
            toParentMessage: (message) => GotComboboxMessage({ message }),
          }),
        ]
      ),
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], [
            "Multiple",
          ]),
          h.div(
            [h.Class("flex flex-wrap gap-2")],
            [
              h.span([h.Class(Combobox.shadcnComboboxTagClassName)], [
                "Next.js",
              ]),
              h.span([h.Class(Combobox.shadcnComboboxTagClassName)], ["Remix"]),
            ]
          ),
          h.div(
            [
              h.Class(
                "rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-500"
              ),
            ],
            ["Select frameworks..."]
          ),
        ]
      ),
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], [
            "Clear Button",
          ]),
          h.div(
            [
              h.Class(
                "flex max-w-sm items-center justify-between rounded-md border border-gray-300 bg-white px-3 py-2 text-sm"
              ),
            ],
            [
              h.span([], ["Next.js"]),
              h.button([h.Type("button"), h.AriaLabel("Clear selection")], [
                "x",
              ]),
            ]
          ),
        ]
      ),
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], ["Groups"]),
          h.div(
            [h.Class(Combobox.shadcnComboboxItemsClassName)],
            [
              h.div([h.Class("px-3 py-1 text-xs font-medium text-gray-500")], [
                "Frontend",
              ]),
              h.div([h.Class(Combobox.shadcnComboboxItemClassName)], [
                "Next.js",
              ]),
              h.div([h.Class(Combobox.shadcnComboboxItemClassName)], [
                "SvelteKit",
              ]),
              h.div([h.Class("px-3 py-1 text-xs font-medium text-gray-500")], [
                "Full-stack",
              ]),
              h.div([h.Class(Combobox.shadcnComboboxItemClassName)], ["Remix"]),
            ]
          ),
        ]
      ),
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], [
            "Custom Items",
          ]),
          h.div(
            [h.Class(Combobox.shadcnComboboxItemsClassName)],
            [
              h.div([h.Class(Combobox.shadcnComboboxItemClassName)], [
                h.div([h.Class("font-medium")], ["Next.js"]),
                h.div([h.Class("text-xs text-gray-500")], [
                  "The React framework for production",
                ]),
              ]),
              h.div([h.Class(Combobox.shadcnComboboxItemClassName)], [
                h.div([h.Class("font-medium")], ["Astro"]),
                h.div([h.Class("text-xs text-gray-500")], [
                  "Content-driven websites",
                ]),
              ]),
            ]
          ),
        ]
      ),
      h.section(
        [h.Class("grid gap-4 md:grid-cols-2")],
        [
          h.div(
            [h.Class("space-y-3")],
            [
              h.h3([h.Class("text-base font-semibold text-gray-950")], [
                "Invalid",
              ]),
              h.input([
                h.AriaLabel("Invalid framework"),
                h.Value("Unknown framework"),
                h.Attribute("aria-invalid", "true"),
                h.Class(
                  `${Combobox.shadcnComboboxInputClassName} rounded-md border border-red-500`
                ),
              ]),
            ]
          ),
          h.div(
            [h.Class("space-y-3")],
            [
              h.h3([h.Class("text-base font-semibold text-gray-950")], [
                "Disabled",
              ]),
              h.input([
                h.AriaLabel("Disabled framework"),
                h.Placeholder("Select framework..."),
                h.Disabled(true),
                h.Class(Combobox.shadcnComboboxInputClassName),
              ]),
            ]
          ),
        ]
      ),
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], [
            "Auto Highlight",
          ]),
          h.div([h.Class(Combobox.shadcnComboboxItemsClassName)], [
            h.div(
              [
                h.Class(Combobox.shadcnComboboxItemClassName),
                h.DataAttribute("active", "true"),
              ],
              ["Next.js"]
            ),
            h.div([h.Class(Combobox.shadcnComboboxItemClassName)], [
              "SvelteKit",
            ]),
          ]),
        ]
      ),
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], ["Popup"]),
          h.button(
            [
              h.Type("button"),
              h.Class(Combobox.shadcnComboboxButtonClassName),
            ],
            ["Open popup"]
          ),
        ]
      ),
      h.section(
        [h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], [
            "Input Group",
          ]),
          h.div(
            [
              h.Class(
                "flex max-w-sm items-center rounded-md border border-gray-300 bg-white"
              ),
            ],
            [
              h.span([h.Class("px-3 text-sm text-gray-500")], ["Framework"]),
              h.input([
                h.AriaLabel("Framework input group"),
                h.Placeholder("Select framework..."),
                h.Class(Combobox.shadcnComboboxInputClassName),
              ]),
            ]
          ),
        ]
      ),
      h.section(
        [h.Attribute("dir", "rtl"), h.Class("space-y-3")],
        [
          h.h3([h.Class("text-base font-semibold text-gray-950")], ["RTL"]),
          h.input([
            h.AriaLabel("إطار العمل"),
            h.Placeholder("اختر إطار العمل..."),
            h.Class(Combobox.shadcnComboboxInputClassName),
          ]),
        ]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Combobox from "../../ui/combobox";
import * as ShadcnComboboxBasicExample from "./main";

const toParentMessage = (message: Combobox.Message) =>
  ShadcnComboboxBasicExample.GotComboboxMessage({ message });

const resolveComboboxMounts = () =>
  Scene.Mount.resolveAll(
    [
      Combobox.AnchorCombobox({
        buttonId: "combobox-basic-input-wrapper",
        anchor: Combobox.defaultAnchor,
      }),
      Combobox.CompletedAnchorCombobox(),
      toParentMessage,
    ],
    [
      Combobox.PortalComboboxBackdrop,
      Combobox.CompletedPortalComboboxBackdrop(),
      toParentMessage,
    ]
  );

const resolvePreventBlurMount = () =>
  Scene.Mount.resolve(
    Combobox.AttachComboboxPreventBlur,
    Combobox.CompletedAttachComboboxPreventBlur(),
    toParentMessage
  );

describe("Shadcn Combobox Basic example", () => {
  test("filters the shadcn framework options", () => {
    Scene.scene(
      {
        update: ShadcnComboboxBasicExample.update,
        view: ShadcnComboboxBasicExample.view,
      },
      Scene.with(ShadcnComboboxBasicExample.init()[0]),
      Scene.expect(Scene.placeholder("Select framework...")).toExist(),
      resolvePreventBlurMount(),
      Scene.type(Scene.placeholder("Select framework..."), "sv"),
      resolveComboboxMounts(),
      Scene.expect(Scene.text("SvelteKit")).toExist(),
      Scene.expect(Scene.text("Next.js")).toExist(),
      Scene.expect(Scene.text("Multiple")).toExist(),
      Scene.expect(Scene.text("Clear Button")).toExist(),
      Scene.expect(Scene.role("button", { name: "Clear selection" })).toExist(),
      Scene.expect(Scene.text("Groups")).toExist(),
      Scene.expect(Scene.text("Frontend")).toExist(),
      Scene.expect(Scene.text("Custom Items")).toExist(),
      Scene.expect(Scene.text("The React framework for production")).toExist(),
      Scene.expect(Scene.role("textbox", { name: "Invalid framework" }))
        .toHaveAttr("aria-invalid", "true"),
      Scene.expect(
        Scene.role("textbox", { name: "Disabled framework" })
      ).toBeDisabled(),
      Scene.expect(Scene.text("Auto Highlight")).toExist(),
      Scene.expect(Scene.text("Popup")).toExist(),
      Scene.expect(Scene.role("button", { name: "Open popup" })).toExist(),
      Scene.expect(
        Scene.role("textbox", { name: "Framework input group" })
      ).toExist(),
      Scene.expect(Scene.role("textbox", { name: "إطار العمل" })).toExist()
    );
  });
});
